import { cacheTag, updateTag } from "next/cache";
import { getAllProducts } from "@/lib/db";

async function ProductListing() {
  "use cache";
  cacheTag("products");

  const products = await getAllProducts();

  return (
    <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
      {products.map((product) => (
        <li
          key={product.id}
          className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800"
        >
          <h3 className="font-semibold text-gray-900 dark:text-white">
            {product.name}
          </h3>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            ${product.price.toLocaleString()}
          </p>
        </li>
      ))}
    </ul>
  );
}

export default function Page() {
  async function invalidateProductsCache() {
    "use server";
    updateTag("products");
  }

  return (
    <div className="mx-auto max-w-4xl space-y-8 p-8">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          Product Catalog
        </h1>
        <form action={invalidateProductsCache}>
          <button
            type="submit"
            className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:bg-gray-100 dark:text-gray-900 dark:hover:bg-gray-200"
          >
            Refresh Products
          </button>
        </form>
      </div>
      <p className="text-sm text-gray-600 dark:text-gray-400">
        Product data is cached for performance. Click &quot;Refresh Products&quot;
        to invalidate the cache and fetch fresh data from the database.
      </p>
      <ProductListing />
    </div>
  );
}

